import fs from 'node:fs';
import path from 'node:path';

const options = JSON.parse(fs.readFileSync(new URL('./provider-options.json', import.meta.url), 'utf8'));

export const apiVersion = 1;

export function generate(context) {
  fs.appendFileSync(options.logPath, 'controller,');
  fs.mkdirSync(path.dirname(context.output), { recursive: true });
  fs.writeFileSync(context.output, '/* Generated by @exprtlabs/ts-to-openapi. Do not edit. */\n{}\n');
  return {
    apiVersion: 1,
    artifacts: [{ path: context.output, content: fs.readFileSync(context.output, 'utf8') }],
    manifestPaths: [],
    watchInputs: [],
  };
}
